import re

_UNITS = {
    1: ("s", "sec", "secs", "second", "seconds"),
    60: ("m", "min", "mins", "minute", "minutes"),
    3600: ("h", "hr", "hrs", "hour", "hours"),
    86400: ("d", "day", "days"),
    604800: ("w", "wk", "wks", "week", "weeks"),
}
_UNIT_MAP = {name: mult for mult, names in _UNITS.items() for name in names}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)\s*")
_ISO = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?"
)
_CLOCK = re.compile(r"(\d+):(\d{1,2})(?::(\d{1,2}(?:\.\d+)?))?")


def _round(total: float) -> int:
    # round half up (avoid banker's rounding)
    return int(total + 0.5)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # bare integer seconds
    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601
    m = _ISO.fullmatch(s.upper())
    if m and any(m.groups()) and not s.upper().endswith("T"):
        mults = (604800, 86400, 3600, 60, 1)
        total = sum(float(g) * k for g, k in zip(m.groups(), mults) if g)
        return _round(total)

    # clock notation
    m = _CLOCK.fullmatch(s)
    if m:
        a, b, c = m.groups()
        if c is None:
            mins, secs = int(a), float(b)
            if secs >= 60:
                raise ValueError(f"invalid clock duration: {text!r}")
            return _round(mins * 60 + secs)
        hrs, mins, secs = int(a), int(b), float(c)
        if mins >= 60 or secs >= 60:
            raise ValueError(f"invalid clock duration: {text!r}")
        return _round(hrs * 3600 + mins * 60 + secs)

    # number+unit components
    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        cm = _COMPONENT.match(s, pos)
        if not cm or cm.end() == pos:
            raise ValueError(f"invalid duration: {text!r}")
        unit = cm.group(2).lower()
        if unit not in _UNIT_MAP:
            raise ValueError(f"unknown unit {cm.group(2)!r} in {text!r}")
        total += float(cm.group(1)) * _UNIT_MAP[unit]
        found = True
        pos = cm.end()
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

